css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .58); position: relative; overflow: hidden; border-radius: 8px; background: color-mix(in srgb, var(--accent-2) 22%, transparent); }
.loader span { position: absolute; left: -22%; width: 144%; border-radius: 50% 50% 0 0 / 100% 100% 0 0; animation: dune-drift calc(var(--loader-speed) * 7) linear infinite; }
.loader span:nth-of-type(1) { bottom: 0; height: 52%; background: var(--accent); }
.loader span:nth-of-type(2) { bottom: 0; height: 38%; background: color-mix(in srgb, #fff 22%, var(--accent)); animation-duration: calc(var(--loader-speed) * 5); animation-delay: calc(var(--loader-speed) * -1.6); }
.loader span:nth-of-type(3) { bottom: 0; height: 24%; background: var(--accent-2); animation-duration: calc(var(--loader-speed) * 3.4); }
.loader i { position: absolute; width: 5%; height: 5%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: dune-grain calc(var(--loader-speed) * 2.4) linear infinite; }
.loader i:nth-of-type(1) { top: 22%; }
.loader i:nth-of-type(2) { top: 40%; animation-delay: calc(var(--loader-speed) * .8); }
.loader i:nth-of-type(3) { top: 12%; animation-delay: calc(var(--loader-speed) * 1.6); }
@keyframes dune-drift { 0%, 100% { transform: translateX(-8%); } 50% { transform: translateX(8%); } }
@keyframes dune-grain { 0% { opacity: 0; left: -6%; } 15%, 80% { opacity: .9; } 100% { opacity: 0; left: 104%; } }
